from __future__ import annotations
import html,json
from collections import Counter
from pathlib import Path

def write_json(path,artifacts,relationships,findings=None):
    data={'artifacts':[a.to_dict() for a in artifacts],'relationships':[r.to_dict() for r in relationships],'findings':findings or []}
    Path(path).write_text(json.dumps(data,indent=2,ensure_ascii=False),encoding='utf-8')

def write_html(path,artifacts,relationships,case_id='LOCAL ANALYSIS',findings=None):
    findings=findings or []
    nodes=[{'id':a.id,'label':a.name[:48],'kind':a.kind,'source':a.source,'timestamp':a.timestamp,'path':a.path,'sha256':a.sha256,'metadata':a.metadata,'observed':a.observed} for a in artifacts]
    edges=[{'from':r.source_id,'to':r.target_id,'label':r.relation,'confidence':r.confidence,'basis':r.basis,'inferred':r.inferred} for r in relationships]
    data=json.dumps({'nodes':nodes,'edges':edges,'findings':findings},ensure_ascii=False).replace('</','<\\/')
    kinds=Counter(a.kind for a in artifacts)
    metrics=f'<div class="metric"><b>{len(artifacts)}</b><span>artifacts</span></div><div class="metric"><b>{len(relationships)}</b><span>links</span></div><div class="metric"><b>{len(findings)}</b><span>findings</span></div>'
    doc='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TRACE — Digital Evidence Analysis</title><style>
:root{--bg:#080a0d;--panel:#101419;--panel2:#151a20;--line:#27303a;--text:#e7edf3;--muted:#89949f;--accent:#70d3ff;--warn:#e2b45f;--bad:#df7777}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{height:72px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 22px;background:#0b0e12}.brand{font-weight:800;letter-spacing:.16em}.case{color:var(--muted);margin-left:15px}.metrics{display:flex;gap:7px}.metric{min-width:78px;padding:6px 10px;border:1px solid var(--line);border-radius:6px;background:var(--panel);text-align:center}.metric b{display:block;font-size:15px}.metric span{font-size:9px;color:var(--muted);text-transform:uppercase}.tabs{height:43px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:3px;padding:0 15px;background:#0d1014}.tab{border:0;background:transparent;color:var(--muted);padding:8px 12px;border-radius:5px;cursor:pointer}.tab.active{background:var(--panel2);color:var(--text)}.view{display:none;height:calc(100vh - 115px)}.view.active{display:grid}.graph{grid-template-columns:1fr 380px}.timeline{grid-template-columns:1fr 380px}.findings{display:block;overflow:auto;padding:24px}.panel{border-left:1px solid var(--line);background:var(--panel);padding:20px;overflow:auto}.canvas{position:relative;overflow:hidden;background:radial-gradient(circle at 50% 45%,#151b21 0,#080a0d 58%)}svg{width:100%;height:100%}.toolbar{position:absolute;z-index:2;left:15px;top:15px;display:flex;gap:6px}.toolbar button,.tab{border:1px solid var(--line);background:var(--panel2);color:var(--text);padding:7px 10px;border-radius:6px;cursor:pointer}.edge{stroke:#56626d;stroke-width:1.5;opacity:.75}.node{cursor:pointer}.node circle{fill:#121820;stroke:#687582;stroke-width:1.5}.node text{fill:#dfe7ee;font-size:10px}.node:hover circle{stroke:var(--accent);stroke-width:2.5}.legend{position:absolute;bottom:14px;left:15px;color:var(--muted);font-size:10px}.eyebrow{color:var(--muted);font-size:9px;letter-spacing:.11em;text-transform:uppercase}.title{font-size:18px;font-weight:650;margin:5px 0 17px;word-break:break-word}.field{margin:10px 0}.label{font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.value{margin-top:3px;word-break:break-word}code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 7px;margin:0 4px 4px 0;color:#bcc7d0;font-size:10px}.relation,.finding{background:#0c1014;border:1px solid var(--line);padding:11px;border-radius:7px;margin:8px 0}.confidence{color:var(--accent);font-weight:650}.basis{margin:6px 0 0;padding-left:16px;color:#aeb9c3}.note{color:var(--muted);font-size:10px;line-height:1.5}.timeline-list{padding:25px;overflow:auto}.event{display:grid;grid-template-columns:170px 130px 1fr;gap:12px;padding:11px 0;border-bottom:1px solid var(--line)}.event time{color:var(--muted);font-family:ui-monospace,monospace;font-size:11px}.event .kind{color:var(--accent);font-size:10px;text-transform:uppercase}.finding .sev{font-size:10px;letter-spacing:.08em;color:var(--warn)}.finding.high .sev{color:var(--bad)}.finding h3{margin:4px 0 6px;font-size:14px}.finding p{color:#b6c0c9;line-height:1.5;margin:0}.empty{color:var(--muted);line-height:1.7}@media(max-width:900px){.view.active{display:block;height:auto}.canvas{height:60vh}.panel{height:45vh;border-left:0;border-top:1px solid var(--line)}.timeline-list{height:60vh}.event{grid-template-columns:1fr}.metrics{display:none}}
</style></head><body><header><div><span class="brand">TRACE</span><span class="case">'''+html.escape(case_id)+''' · DIGITAL EVIDENCE ANALYSIS</span></div><div class="metrics">'''+metrics+'''</div></header><nav class="tabs"><button class="tab active" data-v="graph">Evidence Graph</button><button class="tab" data-v="timeline">Timeline</button><button class="tab" data-v="findings">Findings</button></nav><section id="graph" class="view active graph"><div class="canvas"><div class="toolbar"><button onclick="render()">Re-layout</button><button onclick="resetView()">Reset</button></div><div class="legend">Observed artifacts are nodes. Edges are explainable inferences. Select a node to inspect its provenance.</div><svg id="svg"></svg></div><aside class="panel" id="inspector"><div class="eyebrow">Evidence inspector</div><div class="title">Select an artifact</div><div class="empty">TRACE separates observed evidence from inferred relationships and shows the basis of every correlation.</div></aside></section><section id="timeline" class="view timeline"><div class="timeline-list" id="timelineList"></div><aside class="panel" id="timelineInspector"><div class="eyebrow">Timeline</div><div class="title">Chronological artifact view</div><div class="empty">Events are sorted by their recorded timestamps. A timestamp is evidence about an artifact, not proof of user intent.</div></aside></section><section id="findings" class="view findings"><div class="eyebrow">Analytical findings</div><div class="title">Indicators requiring review</div><div class="note">Findings are deliberately conservative. An indicator is not an attribution or a conclusion of wrongdoing.</div><div id="findingList"></div></section><script>const DATA='''+data+''';const svg=document.getElementById('svg'),ins=document.getElementById('inspector');let pos={};const NS='http://www.w3.org/2000/svg';function esc(s){return String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}function render(){const w=svg.clientWidth||900,h=svg.clientHeight||700,n=DATA.nodes.length;pos={};DATA.nodes.forEach((x,i)=>{const a=i/Math.max(n,1)*Math.PI*2-Math.PI/2,r=Math.min(w,h)*.34;pos[x.id]={x:w/2+Math.cos(a)*r,y:h/2+Math.sin(a)*r}});svg.innerHTML='';DATA.edges.forEach(e=>{const a=pos[e.from],b=pos[e.to];if(!a||!b)return;const l=document.createElementNS(NS,'line');l.setAttribute('x1',a.x);l.setAttribute('y1',a.y);l.setAttribute('x2',b.x);l.setAttribute('y2',b.y);l.className.baseVal='edge';svg.appendChild(l)});DATA.nodes.forEach(x=>{const p=pos[x.id],g=document.createElementNS(NS,'g');g.className.baseVal='node';g.onclick=()=>inspect(x.id);const c=document.createElementNS(NS,'circle');c.setAttribute('cx',p.x);c.setAttribute('cy',p.y);c.setAttribute('r',13);g.appendChild(c);const t=document.createElementNS(NS,'text');t.setAttribute('x',p.x);t.setAttribute('y',p.y+29);t.setAttribute('text-anchor','middle');t.textContent=x.label;g.appendChild(t);svg.appendChild(g)})}function inspect(id){const x=DATA.nodes.find(n=>n.id===id),rs=DATA.edges.filter(e=>e.from===id||e.to===id);let s='<div class="eyebrow">'+esc(x.kind)+' · '+esc(x.source)+'</div><div class="title">'+esc(x.label)+'</div><span class="pill">OBSERVED</span>';for(const [k,v] of [['Timestamp',x.timestamp],['Path',x.path],['SHA-256',x.sha256]])if(v)s+='<div class="field"><div class="label">'+k+'</div><div class="value"><code>'+esc(v)+'</code></div></div>';if(x.metadata&&Object.keys(x.metadata).length){s+='<div class="section"><div class="eyebrow">Metadata</div>';Object.entries(x.metadata).slice(0,35).forEach(([k,v])=>s+='<div class="field"><div class="label">'+esc(k)+'</div><div class="value">'+esc(typeof v==='object'?JSON.stringify(v):v)+'</div></div>');s+='</div>'}s+='<div class="section"><div class="eyebrow">Correlations ('+rs.length+')</div>';rs.forEach(e=>{const other=DATA.nodes.find(n=>n.id===(e.from===id?e.to:e.from));s+='<div class="relation"><b>'+esc(e.label)+'</b> · <span class="confidence">'+Math.round(e.confidence*100)+'%</span><div class="note">'+esc(other?.label||'')+'</div><ul class="basis">'+e.basis.map(b=>'<li>'+esc(b)+'</li>').join('')+'</ul><div class="note">INFERRED — review supporting artifacts before drawing conclusions.</div></div>'});s+='</div>';ins.innerHTML=s}function resetView(){document.getElementById('inspector').innerHTML='<div class="eyebrow">Evidence inspector</div><div class="title">Select an artifact</div><div class="empty">Select a node in the graph.</div>';render()}function populate(){const list=DATA.nodes.filter(x=>x.timestamp).sort((a,b)=>String(a.timestamp).localeCompare(String(b.timestamp)));document.getElementById('timelineList').innerHTML=list.map(x=>'<div class="event"><time>'+esc(x.timestamp)+'</time><div class="kind">'+esc(x.kind)+'</div><div><b>'+esc(x.label)+'</b><div class="note">'+esc(x.path||x.metadata?.url||'')+'</div></div></div>').join('')||'<div class="empty">No timestamped artifacts.</div>';document.getElementById('findingList').innerHTML=DATA.findings.length?DATA.findings.map(f=>'<div class="finding '+(f.severity==='HIGH'?'high':'')+'"><div class="sev">'+esc(f.severity)+'</div><h3>'+esc(f.title)+'</h3><p>'+esc(f.detail)+'</p><div class="note">Basis: '+esc(f.basis.join('; '))+'</div></div>').join(''):'<div class="finding"><h3>No automated findings</h3><p>TRACE did not identify any rule-based indicators requiring review.</p></div>'}document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.v).classList.add('active');if(b.dataset.v==='graph')setTimeout(render,0)});window.addEventListener('resize',render);populate();render();</script></body></html>'''
    Path(path).write_text(doc,encoding='utf-8')
